(6691118, 1000586, 96751, '<td valign="top">Awwwwww.  That is so sweet.</td>', 'Awwwwww.  That is so sweet.', '2012-02-24 16:02:38.000000', NULL, 1),
(6691120, 1000585, 96751, '<td valign="top">Wonderful framing.  Love the shot, although there might be too much of the washed out thing</td>', 'Wonderful framing.  Love the shot, although there might be too much of the washed out thing', '2012-02-24 16:03:18.000000', NULL, 1),
(6691121, 1000209, 96751, '<td valign="top">Ha!!!!  Adorable</td>', 'Ha!!!!  Adorable', '2012-02-24 16:03:31.000000', NULL, 1),
